import{_ as r,o as d,c as a,a4 as e}from"./chunks/framework.CeDiN6Rk.js";const o="/diagrams/latium-tiers.svg",h="/diagrams/albion-tiers.svg",n="/diagrams/aegyptus-tiers.svg",m=JSON.parse('{"title":"住民層","description":"Anno 117のラティウム（ローマ）・アルビオン（ケルト）・アイギュプト（DLC03）の住民層と昇格条件、需要システムの仕組みを解説。","frontmatter":{"title":"住民層","description":"Anno 117のラティウム（ローマ）・アルビオン（ケルト）・アイギュプト（DLC03）の住民層と昇格条件、需要システムの仕組みを解説。"},"headers":[],"relativePath":"wiki/population.md","filePath":"wiki/population.md"}'),l={name:"wiki/population.md"};function s(i,t,b,p,g,c){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="住民層" tabindex="-1">住民層 <a class="header-anchor" href="#住民層" aria-label="Permalink to &quot;住民層&quot;">​</a></h1><p>Anno 117 には<strong>ラティウム（ローマ）</strong>と<strong>アルビオン（ケルト）</strong>の2系統の住民層があります。DLC03「デルタの夜明け」（2026年11月5日追加）で、3系統目の<strong>アイギュプト（エジプト）</strong>が加わりました。</p><h2 id="需要システムの仕組み" tabindex="-1">需要システムの仕組み <a class="header-anchor" href="#需要システムの仕組み" aria-label="Permalink to &quot;需要システムの仕組み&quot;">​</a></h2><ul><li><strong>カテゴリ制:</strong> 各層に食料・ファッション・家庭・公共などのカテゴリがあり、各カテゴリを100％以上にすることで上位層へ昇格できます</li><li><strong>需要率:</strong> 同一カテゴリ内の複数品目は「100～200％の範囲」。100％以上供給すると住民の収入等が増加します</li><li><strong>上位互換消費:</strong> 上位層の住民も下位層の需要を引き続き消費します</li></ul><hr><h2 id="ラティウム住民層" tabindex="-1">ラティウム住民層 <a class="header-anchor" href="#ラティウム住民層" aria-label="Permalink to &quot;ラティウム住民層&quot;">​</a></h2><p><img src="'+o+'" alt="ラティウム住民層の進化"></p><h3 id="リベルトゥス" tabindex="-1">リベルトゥス <a class="header-anchor" href="#リベルトゥス" aria-label="Permalink to &quot;リベルトゥス&quot;">​</a></h3><p>ラティウムの最下層住民です。ゲーム開始時から存在する基本労働力です。</p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>イワシ（必須）、お粥、パン（輝きで追加）、ビール（研究で追加）</td></tr><tr><td>ファッション</td><td>チュニック、ピレウス帽</td></tr><tr><td>公共サービス</td><td>市場、酒場</td></tr></tbody></table><ul><li><strong>パン</strong>：円形闘技場の輝きがランクIVになると加わる需要です（アップデート2.0から）。気づかないうちにパンの消費が増えるので注意。この消費量は、アップデート3.0でプレブスと同じ水準まで下がりました。詳しくは<a href="/wiki/splendor.html">モニュメントの輝き</a>にあります。</li><li><strong>ビール</strong>：社会のスキル「ケレースとバッカス」を研究すると加わる需要です。満たすと人口+1・収入+1・幸福+2、知識は-1です（ゲーム内データの値で、実機では未確認です）。スキルは<a href="/wiki/techs-civic.html">スキルツリー・社会</a>にあります。</li></ul><hr><h3 id="プレブス" tabindex="-1">プレブス <a class="header-anchor" href="#プレブス" aria-label="Permalink to &quot;プレブス&quot;">​</a></h3><p>リベルトゥスの需要を充足後にアップグレードできます。</p><p><strong>追加需要（プレブス固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>パン、ガルム</td></tr><tr><td>ファッション</td><td>サンダル、石鹸</td></tr><tr><td>家庭</td><td>アンフォラ、オリーブオイル</td></tr><tr><td>公共サービス</td><td>聖域、ラテン語学校</td></tr></tbody></table><hr><h3 id="エクィテス" tabindex="-1">エクィテス <a class="header-anchor" href="#エクィテス" aria-label="Permalink to &quot;エクィテス&quot;">​</a></h3><p>プレブスの需要を充足後にアップグレードできます。</p><p><strong>追加需要（エクィテス固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>ワイン、チーズ</td></tr><tr><td>ファッション</td><td>トガ、ブローチ</td></tr><tr><td>家庭</td><td>筆記板、高級ガラス、小像</td></tr><tr><td>公共サービス</td><td>貯水池、劇場、賭博場</td></tr><tr><td>驚異</td><td>公共広場、浴場</td></tr></tbody></table><p><strong>アップデート3.0で追加された需要:</strong> アイギュプトの商品が加わりました。食料の<strong>ナツメヤシ</strong>、ファッションの<strong>コール</strong>、家庭の<strong>書記道具一式</strong>です。ナツメヤシの画面には「必要な品物が生産できる場所: アイギュプト」と出ます。ラティウムの島で満たすには、アイギュプトで作った商品を運んでくる必要があります。</p><hr><h3 id="パトリキ" tabindex="-1">パトリキ <a class="header-anchor" href="#パトリキ" aria-label="Permalink to &quot;パトリキ&quot;">​</a></h3><p>エクィテスの需要を充足後にアップグレードできます。最高税収・威信を誇る最上位層です。</p><p><strong>追加需要（パトリキ固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>牡蠣のキャビア添え、鳥舌肉アスピック</td></tr><tr><td>ファッション</td><td>ネックレス、外套</td></tr><tr><td>家庭</td><td>肘掛け椅子、手鏡</td></tr><tr><td>公共サービス</td><td>神殿、図書館</td></tr><tr><td>驚異</td><td>円形闘技場</td></tr></tbody></table><p><strong>アップデート3.0で追加された需要:</strong> エクィテスと同じアイギュプトの3商品（ナツメヤシ・コール・書記道具一式）に加えて、食料の<strong>カフク</strong>、ファッションの<strong>ポッパエアのミルク</strong>、家庭の<strong>象牙の小箱</strong>、文化の<strong>シストラム</strong>が加わりました。どれもアイギュプトの商品です。</p><hr><h2 id="アルビオン住民層" tabindex="-1">アルビオン住民層 <a class="header-anchor" href="#アルビオン住民層" aria-label="Permalink to &quot;アルビオン住民層&quot;">​</a></h2><p>アルビオンでは Tier 2 以降に<strong>ケルト文化</strong>と<strong>ローマ文化</strong>の2つの路線があります。</p><p><img src="'+h+'" alt="アルビオン住民層の進化"></p><h3 id="ウェーダー" tabindex="-1">ウェーダー <a class="header-anchor" href="#ウェーダー" aria-label="Permalink to &quot;ウェーダー&quot;">​</a></h3><p>アルビオンの共通基本層です。文化選択前の住民です。</p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>ザル貝（必須）、ウナギ（必須）</td></tr><tr><td>ファッション</td><td>チュニック、葦の靴</td></tr><tr><td>公共サービス</td><td>市場、吟遊詩人の暖炉</td></tr></tbody></table><hr><h3 id="スミス-ケルト文化路線" tabindex="-1">スミス（ケルト文化路線） <a class="header-anchor" href="#スミス-ケルト文化路線" aria-label="Permalink to &quot;スミス（ケルト文化路線）&quot;">​</a></h3><p>ウェーダーがケルト文化を選択した場合に進化します。</p><p><strong>追加需要（スミス固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>チーズ、ビール</td></tr><tr><td>ファッション</td><td>ズボン、首輪</td></tr><tr><td>家庭</td><td>角杯、部族の盾</td></tr><tr><td>公共サービス</td><td>運動場、聖所</td></tr></tbody></table><p><strong>アップデート3.0で追加された需要:</strong> アイギュプトの商品が加わりました。ファッションの<strong>コール</strong>、家庭の<strong>魔除けのお守り</strong>です。</p><hr><h3 id="アルダー-ケルト文化路線" tabindex="-1">アルダー（ケルト文化路線） <a class="header-anchor" href="#アルダー-ケルト文化路線" aria-label="Permalink to &quot;アルダー（ケルト文化路線）&quot;">​</a></h3><p>スミスの需要を充足後にアップグレードできます。ケルト文化の長老・指導者層です。</p><p><strong>追加需要（アルダー固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>ローストビーフ、ワイン</td></tr><tr><td>ファッション</td><td>外套、毛皮の帽子</td></tr><tr><td>家庭</td><td>戦車、高級ガラス</td></tr><tr><td>公共サービス</td><td>厠所、市議会、劇場、賭博場</td></tr><tr><td>驚異</td><td>塚、神聖な森</td></tr></tbody></table><p><strong>アップデート3.0で追加された需要:</strong> アイギュプトの商品が加わりました。食料の<strong>青スイレン茶</strong>、ファッションの<strong>コール</strong>、家庭の<strong>魔除けのお守り</strong>です。画面には「必要な品物が生産できる場所: アイギュプト」と出ます。</p><hr><h3 id="メルカトル-ローマ文化路線" tabindex="-1">メルカトル（ローマ文化路線） <a class="header-anchor" href="#メルカトル-ローマ文化路線" aria-label="Permalink to &quot;メルカトル（ローマ文化路線）&quot;">​</a></h3><p>ウェーダーがローマ文化を選択した場合に進化します。</p><p><strong>追加需要（メルカトル固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>パン、ソーセージ</td></tr><tr><td>ファッション</td><td>ブローチ、石鹸</td></tr><tr><td>家庭</td><td>アンフォラ、オリーブオイル</td></tr><tr><td>公共サービス</td><td>ラテン語学校、聖所</td></tr></tbody></table><p><strong>アップデート3.0で追加された需要:</strong> アイギュプトの商品が加わりました。家庭の<strong>書記道具一式</strong>です。</p><hr><h3 id="ノビレス-ローマ文化路線" tabindex="-1">ノビレス（ローマ文化路線） <a class="header-anchor" href="#ノビレス-ローマ文化路線" aria-label="Permalink to &quot;ノビレス（ローマ文化路線）&quot;">​</a></h3><p>メルカトルの需要を充足後にアップグレードできます。ローマ貴族文化に傾倒した上流層です。</p><p><strong>追加需要（ノビレス固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>鳥舌肉アスピック、ワイン</td></tr><tr><td>ファッション</td><td>かつら、トガ</td></tr><tr><td>家庭</td><td>手鏡、高級ガラス</td></tr><tr><td>公共サービス</td><td>貯水池、劇場、賭博場</td></tr><tr><td>驚異</td><td>神殿、浴場</td></tr></tbody></table><p><strong>アップデート3.0で追加された需要:</strong> アイギュプトの商品が加わりました。食料の<strong>希少な肉の盛り合わせ</strong>、ファッションの<strong>香油</strong>、家庭の<strong>書記道具一式</strong>です。どれも画面には「必要な品物が生産できる場所: アイギュプト」と出ます（希少な肉の盛り合わせはギムナシアリコス、書記道具一式は書記、香油は奉唱巫女の層）。</p><hr><h2 id="アイギュプト住民層" tabindex="-1">アイギュプト住民層 <a class="header-anchor" href="#アイギュプト住民層" aria-label="Permalink to &quot;アイギュプト住民層&quot;">​</a></h2><blockquote><p>層と需要の内容は、ゲームのアップデート3.0のゲーム内データです。需要の数量と昇格条件は載せていません。実機の画面との照合は未確認です。上位の層は、下位の層の需要も引き続き消費します（下の表は、1つ下の層から増える需要です）。</p><p>出典: <a href="https://www.anno-union.com/gamescom-recap-dawn-of-the-delta-and-echoes-of-kassandra/" target="_blank" rel="noreferrer">Anno Union公式ブログ「Gamescom recap: Dawn of the Delta and Echoes of Kassandra」</a>（2026年9月3日）、<a href="https://www.anno-union.com/devblog-population-floods-and-the-power-of-knowledge/" target="_blank" rel="noreferrer">「Population, Floods and the power of knowledge」</a>（デブログ第2回、2026年10月22日）</p></blockquote><p>アイギュプトでは、最初の層から<strong>ギリシャ・ローマ文化</strong>と<strong>クマト文化</strong>の2つの路線に分かれます。各路線は3段階で、最初の麦打ち人の上に、路線ごとの第2階層と第3階層が続きます。</p><p><img src="'+n+'" alt="アイギュプト住民層の進化"></p><h3 id="麦打ち人" tabindex="-1">麦打ち人 <a class="header-anchor" href="#麦打ち人" aria-label="Permalink to &quot;麦打ち人&quot;">​</a></h3><p>アイギュプトの最初の層です。この土地の農業の伝統を担います。</p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>ナツメヤシ、お粥</td></tr><tr><td>ファッション</td><td>ウェセクの首輪、チュニック</td></tr><tr><td>公共サービス</td><td>市場、焚き火</td></tr></tbody></table><hr><h3 id="書記-ギリシャ・ローマ文化路線" tabindex="-1">書記（ギリシャ・ローマ文化路線） <a class="header-anchor" href="#書記-ギリシャ・ローマ文化路線" aria-label="Permalink to &quot;書記（ギリシャ・ローマ文化路線）&quot;">​</a></h3><p>ギリシャ・ローマ文化と融合する路線です。麦打ち人の需要を満たすと上がれます。</p><p><strong>追加需要（書記固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>パン、チーズ</td></tr><tr><td>ファッション</td><td>サンダル、石鹸、ブローチ</td></tr><tr><td>家庭</td><td>書記道具一式、オリーブオイル</td></tr><tr><td>公共サービス</td><td>ラテン語学校、聖域</td></tr></tbody></table><p>学者や行政官の層で、ギリシャ文化の影響が強く、エジプト人をやや見下す傾向があります。書記道具一式は、パピルス（葦が必要）と、現地の鉱物から作る顔料で作ります。</p><hr><h3 id="ギムナシアリコス-ギリシャ・ローマ文化路線の第3階層" tabindex="-1">ギムナシアリコス（ギリシャ・ローマ文化路線の第3階層） <a class="header-anchor" href="#ギムナシアリコス-ギリシャ・ローマ文化路線の第3階層" aria-label="Permalink to &quot;ギムナシアリコス（ギリシャ・ローマ文化路線の第3階層）&quot;">​</a></h3><p>商業で富を得た、教養のある上流層です。</p><p><strong>追加需要（ギムナシアリコス固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>希少な肉の盛り合わせ、ワイン、鳥舌肉アスピック</td></tr><tr><td>ファッション</td><td>ネックレス、ポッパエアのミルク、かつら</td></tr><tr><td>家庭</td><td>象牙の小箱、肘掛け椅子</td></tr><tr><td>公共サービス</td><td>貯水池、劇場、賭博場</td></tr><tr><td>驚異</td><td>浴場、図書館、改修されたピラミッド</td></tr></tbody></table><p>威信と収入が大きく増えます。ローマ式の公共施設（劇場・浴場・図書館）が使えます。浴場には水道橋が必要で、水道橋は灌漑にも使います。</p><hr><h3 id="陶工-クマト文化路線" tabindex="-1">陶工（クマト文化路線） <a class="header-anchor" href="#陶工-クマト文化路線" aria-label="Permalink to &quot;陶工（クマト文化路線）&quot;">​</a></h3><p>クマトの伝統を守る路線で、革新には消極的です。麦打ち人の需要を満たすと上がれます。</p><p><strong>追加需要（陶工固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>詰め物入りガチョウ、ビール</td></tr><tr><td>ファッション</td><td>シェンティ、コール</td></tr><tr><td>家庭</td><td>魔除けのお守り、オイルランプ、角杯、小像</td></tr><tr><td>公共サービス</td><td>薬屋、聖域</td></tr></tbody></table><p>魔除けのお守りは、銅と砂から作った青い染料で、現地の粘土を染めて作ります。</p><hr><h3 id="奉唱巫女-クマト文化路線の第3階層" tabindex="-1">奉唱巫女（クマト文化路線の第3階層） <a class="header-anchor" href="#奉唱巫女-クマト文化路線の第3階層" aria-label="Permalink to &quot;奉唱巫女（クマト文化路線の第3階層）&quot;">​</a></h3><p>陶工を満足させると解放される、女司祭の層です。</p><p><strong>追加需要（奉唱巫女固有）:</strong></p><table tabindex="0"><thead><tr><th>カテゴリ</th><th>商品・施設</th></tr></thead><tbody><tr><td>食料</td><td>カフク、青スイレン茶</td></tr><tr><td>ファッション</td><td>カラシリス、香油、外套</td></tr><tr><td>家庭</td><td>シストラム、高級ガラス、手鏡</td></tr><tr><td>公共サービス</td><td>岩窟墓、劇場、賭博場</td></tr><tr><td>驚異</td><td>神殿、天文台、改修されたピラミッド</td></tr></tbody></table><p>「改修されたピラミッド」は、州全体のプロジェクトで修復したピラミッドが満たす需要です。ゲーム内のヘルプ（ピラミッドの改修）では、修復されたピラミッドは、誰が修復を完了したかに関わらず、アイギュプトのすべての奉唱巫女とギムナシアリコスの公共サービス需要を満たす、と説明されています。自分で建てる建物ではありません。</p><p>どれも高価ですが、満足度と威信が大きく上がります。シストラムは、現地の銅と錫から作った青銅に、氾濫原のビーズを組み合わせて作ります。</p><hr><h3 id="路線ごとの公共施設" tabindex="-1">路線ごとの公共施設 <a class="header-anchor" href="#路線ごとの公共施設" aria-label="Permalink to &quot;路線ごとの公共施設&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路線</th><th>施設</th></tr></thead><tbody><tr><td>クマト文化</td><td>薬屋（薬草園つき。健康と知識）、聖域または神殿（現地の神々）、岩窟墓（上流階級向け。山のスロットが必要）、天文台（信仰+5、知識+3）</td></tr><tr><td>ギリシャ・ローマ文化</td><td>劇場、浴場（水道橋が必要）、図書館（オイルランプに注意）</td></tr></tbody></table><h2 id="関連データ" tabindex="-1">関連データ <a class="header-anchor" href="#関連データ" aria-label="Permalink to &quot;関連データ&quot;">​</a></h2><ul><li><a href="/wiki/needs-index.html">商品需要逆引き</a> — 商品からどの住民層の需要かを調べる</li><li><a href="/wiki/buildings.html">建物効果</a> — 住民の幸福・健康などに効く建物</li><li><a href="/guide/dlc03-dawn-of-delta.html">DLC03・デルタの夜明け</a> — アイギュプトの発表済み情報</li></ul><h2 id="関連ガイド" tabindex="-1">関連ガイド <a class="header-anchor" href="#関連ガイド" aria-label="Permalink to &quot;関連ガイド&quot;">​</a></h2><ul><li><a href="/guide/early-game-strategy.html">序盤攻略・基本戦略</a> — 住民層と需要充足の基本</li><li><a href="/guide/economy-guide.html">経済・収入最適化ガイド</a> — 住民ティアと必要需要の詳細</li></ul>',99)])])}const f=r(l,[["render",s]]);export{m as __pageData,f as default};
